# Python program to find a partition of the given set into 15 triples (a,b,c) with a+b=c
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
N = 15
from itertools import combinations

def search(elements, triples):
    if not elements:
        return triples
    # choose a potential c (largest element) to limit branching
    c = max(elements)
    # try all pairs (a,b) in remaining elements that sum to c
    for a in elements:
        if a == c:
            continue
        b = c - a
        if b in elements and b != a:
            # ensure ordering to avoid duplicate pairs
            if a > b:
                continue
            new_elems = set(elements)
            new_elems.remove(a)
            new_elems.remove(b)
            new_elems.remove(c)
            res = search(new_elems, triples + [(a, b, c)])
            if res is not None:
                return res
    return None

solution = search(L, [])
if solution:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "No partition exists because exhaustive search failed to find one."}
print("WITNESS: " + __import__('json').dumps(witness))

#!/usr/bin/env python3
import json, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
N = 15
nums = sorted(L)
# Precompute possible triples (a,b,c) with a+b=c
triples = []
setL = set(nums)
for i in range(len(nums)):
    a = nums[i]
    for j in range(i+1, len(nums)):
        b = nums[j]
        c = a + b
        if c in setL and c!=a and c!=b:
            triples.append((a,b,c))
# Sort triples to try smaller ones first (helps pruning)
triples.sort()
used = set()
solution = []

def backtrack(start):
    if len(solution) == N:
        return True
    for idx in range(start, len(triples)):
        a,b,c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # prune: remaining numbers must be enough
        used.update((a,b,c))
        solution.append((a,b,c))
        if backtrack(idx+1):
            return True
        solution.pop()
        used.difference_update((a,b,c))
    return False

found = backtrack(0)
if found:
    witness = {"polarity":"positive","data":{"partition":solution}}
else:
    witness = {"polarity":"negative","basis":"search","search_exhausted":true,"argument":"No partition exists for given set."}
print('WITNESS:', json.dumps(witness))
